import { Injectable } from '@angular/core';

// 1. Importaciones compatibles con Angular moderno
// @ts-ignore
import pdfMake from 'pdfmake/build/pdfmake';
// @ts-ignore
import pdfFonts from 'pdfmake/build/vfs_fonts';

import { TDocumentDefinitions } from 'pdfmake/interfaces';
import { ReporteIndisciplina, PerfilUsuarioDTO, RolEstudiante, Materia, RolEmpleado, BoletaDataDTO } from '../ModelosActivos/ModelosAplicacion.model';
import { GrupoDetalle } from './grupos.service';

// Configuración de fuentes
(pdfMake as any).vfs = pdfFonts.vfs;

@Injectable({
  providedIn: 'root'
})
export class ImpresionService {

  constructor() { }

  // --- ASSETS ---

  // 1. LOGO DEL COLEGIO (Base64)
  // IMPORTANTE: Reemplaza esta cadena corta por el Base64 real de tu logo PNG/JPG.
  // Puedes generarlo aquí: https://www.base64-image.de/
  private logoColegio = 'data:image/png;base64,';

  // 2. AVATAR POR DEFECTO (Silueta Gris)
  private defaultAvatar = 'data:image/png;base64,';
  
  /**
   * Genera el reporte oficial de lista de asistencia/grupo.
   */
  imprimirListaGrupo(grupo: GrupoDetalle, estudiantes: PerfilUsuarioDTO[]) {
    
    const guinda = '#8C1D40';
    const grisClaro = '#6B7280';
    const grisOscuro = '#1F2937';
    const fondoTabla = '#f9fafb';

    // Ordenar estudiantes alfabéticamente
    const listaOrdenada = estudiantes.sort((a, b) => 
      a.persona.apellidos.localeCompare(b.persona.apellidos)
    );

    // Construir filas de la tabla
    const tableBody: any[] = [ 
      // Encabezados
      [
        { text: 'NO.', style: 'tableHeader', fillColor: guinda, color: 'white' },
        { text: 'MATRÍCULA', style: 'tableHeader', fillColor: guinda, color: 'white' },
        { text: 'NOMBRE DEL ESTUDIANTE', style: 'tableHeader', fillColor: guinda, color: 'white' },
        { text: 'FIRMA / ASISTENCIA', style: 'tableHeader', fillColor: guinda, color: 'white', alignment: 'center' }
      ]
    ];

    // Filas de datos
    listaOrdenada.forEach((est, index) => {
      const rol = est.rol as RolEstudiante;
      tableBody.push([
        { text: (index + 1).toString(), style: 'tableCell', alignment: 'center' },
        { text: rol?.matricula || '---', style: 'tableCellMono' },
        { text: `${est.persona.apellidos} ${est.persona.nombre}`, style: 'tableCell' },
        { text: '', style: 'tableCell' } // Espacio para firmar
      ]);
    });

    const docDefinition: TDocumentDefinitions = {
      pageSize: 'LETTER',
      pageMargins: [40, 60, 40, 60],
      
      content: [
        // 1. ENCABEZADO
        {
          columns: [
            { image: this.logoColegio, width: 50 },
            {
              stack: [
                { text: 'COLEGIO VIZCAYA', style: 'brandTitle' },
                { text: 'CONTROL ESCOLAR - LISTA DE GRUPO', style: 'brandSubTitle' }
              ],
              alignment: 'center', width: '*'
            },
            {
              stack: [
                { text: 'CICLO', style: 'labelTiny', alignment: 'right' },
                { text: grupo.cicloEscolar, style: 'folioText', alignment: 'right' }
              ],
              width: 80
            }
          ]
        },
        
        { canvas: [{ type: 'line', x1: 0, y1: 10, x2: 532, y2: 10, lineWidth: 2, lineColor: guinda }] },
        { text: '', margin: [0, 0, 0, 15] },

        // 2. DATOS DEL GRUPO (Tarjeta Informativa)
        {
          style: 'infoCard',
          table: {
            widths: ['*', '*', '*'],
            body: [
              [
                { text: 'ASIGNATURA', style: 'labelTiny' },
                { text: 'DOCENTE TITULAR', style: 'labelTiny' },
                { text: 'GRADO Y GRUPO', style: 'labelTiny' }
              ],
              [
                { text: grupo.materia.nombre, style: 'dataTextBig' },
                { text: grupo.docente ? `${grupo.docente.persona.nombre} ${grupo.docente.persona.apellidos}` : 'SIN ASIGNAR', style: 'dataText' },
                { text: `${grupo.materia.grado}° Semestre`, style: 'dataText' }
              ]
            ]
          },
          layout: 'noBorders'
        },

        { text: '', margin: [0, 0, 0, 20] },

        // 3. TABLA DE ALUMNOS
        {
          table: {
            headerRows: 1,
            widths: [30, 80, '*', 100],
            body: tableBody as any
          },
          layout: {
            hLineWidth: (i) => (i === 0 || i === 1) ? 1 : 0.5, // Líneas horizontales
            vLineWidth: () => 0, // Sin líneas verticales
            hLineColor: (i) => (i === 0) ? guinda : '#e5e7eb',
            paddingTop: () => 8,
            paddingBottom: () => 8
          }
        },

        // 4. PIE
        {
          text: `Total de Alumnos Inscritos: ${listaOrdenada.length}`,
          style: 'footerText', margin: [0, 20, 0, 0]
        }
      ],

      styles: {
        brandTitle: { fontSize: 14, bold: true, color: guinda },
        brandSubTitle: { fontSize: 8, color: grisClaro, characterSpacing: 1 },
        labelTiny: { fontSize: 7, color: grisClaro, bold: true, },
        folioText: { fontSize: 10, bold: true, color: guinda },
        dataText: { fontSize: 10, color: grisOscuro, bold: true },
        dataTextBig: { fontSize: 11, color: guinda, bold: true },
        
        tableHeader: { fontSize: 8, bold: true, alignment: 'left', margin: [0, 2] },
        tableCell: { fontSize: 9, color: grisOscuro },
        tableCellMono: { fontSize: 9, color: grisClaro, fontFeatures: ['tnum'] }, // Números tabulares
        
        footerText: { fontSize: 9, bold: true, alignment: 'right', color: guinda }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }

  /**
   * Genera la Boleta de Calificaciones.
   * Ajuste: Encabezado Centrado y Márgenes Estándar.
   */
  imprimirBoleta(data: BoletaDataDTO) {
    
    // --- 1. CONFIGURACIÓN VISUAL (Identidad Vizcaya) ---
    const guinda = '#8C1D40';
    const grisOscuro = '#374151'; // Gray-700
    const grisClaro = '#9CA3AF';  // Gray-400
    const grisFondo = '#F3F4F6';  // Gray-100
    const lineaSuave = '#E5E7EB'; // Gray-200

    // Datos Oficiales (Estos podrían venir de un archivo de configuración)
    const CCT = '10PBT0000X'; 
    const RVOE = '20202020';
    const FECHA_RVOE = '15/08/2010';

    // --- 2. PROCESAMIENTO DE DATOS ---

    // A. Ordenar Periodos Cronológicamente
    const periodosOrdenados = data.periodos.sort((a, b) => 
      new Date(a.fechaInicio).getTime() - new Date(b.fechaInicio).getTime()
    );

    // B. Calcular Anchos de Tabla Dinámicos
    // Si hay muchos periodos, las columnas se hacen más angostas
    const anchoPeriodo = periodosOrdenados.length > 3 ? 25 : 35;
    // Estructura: [Materia (Flexible), ...Periodos (Fijos), Promedio (Fijo)]
    const tableWidths: any[] = ['*', ...periodosOrdenados.map(() => anchoPeriodo), 45]; 

    // C. Construir Encabezados de la Tabla de Calificaciones
    const headerRow: any[] = [
      { text: 'ASIGNATURA', style: 'th', alignment: 'center' }
    ];

    periodosOrdenados.forEach(p => {
      // Usamos las primeras 3 letras del periodo (Ej: "PAR 1", "SEM 1")
      headerRow.push({ 
        text: p.nombre.substring(0, 10).toUpperCase(), 
        style: 'th', 
        alignment: 'center' 
      });
    });

    headerRow.push({ text: 'PROMEDIO', style: 'th', alignment: 'center', fillColor: guinda });

    // D. Construir Cuerpo de la Tabla y Calcular Promedios
    const tableBody: any[] = [headerRow];
    let sumaPromedios = 0;
    let materiasConPromedio = 0;
    let reprobadas = 0;

    // Filtramos materias con observaciones para la sección final
    const materiasConObservacion = data.resultados.filter(r => r.observaciones && r.observaciones.trim() !== '');

    data.resultados.forEach((res, index) => {
      // Efecto cebra para las filas
      const bgRow = index % 2 === 0 ? 'white' : '#F9FAFB';
      
      // Fila Base: Nombre de Materia
      const row: any[] = [
        { text: res.materia.nombre, style: 'td', alignment: 'left', fillColor: bgRow, bold: true }
      ];

      // Columnas de Periodos
      periodosOrdenados.forEach(p => {
        const calif = res.calificacionesPorPeriodo[p.id];
        let textoCalif = '-';
        let colorCalif = grisOscuro;
        let esBold = false;

        if (calif !== null && calif !== undefined) {
          textoCalif = calif.toString();
          // Regla SEP: Reprobatorias (<6) en Rojo y Negrita
          if (calif < 6) {
            colorCalif = '#DC2626'; 
            esBold = true;
          }
        }
        row.push({ text: textoCalif, style: 'td', color: colorCalif, bold: esBold, alignment: 'center', fillColor: bgRow });
      });

      // Columna Promedio Final
      let colorProm = grisOscuro;
      let boldProm = false;
      // Si tiene promedio y es reprobatorio
      if (res.promedioFinal < 6 && res.promedioFinal > 0) {
        colorProm = '#DC2626';
        boldProm = true;
        reprobadas++;
      }
      
      row.push({ 
        text: res.promedioFinal > 0 ? res.promedioFinal.toFixed(1) : '-', 
        style: 'tdProm', 
        color: colorProm,
        bold: boldProm,
        fillColor: grisFondo 
      });

      tableBody.push(row);

      // Acumuladores para el promedio general
      if (res.promedioFinal > 0) {
        sumaPromedios += res.promedioFinal;
        materiasConPromedio++;
      }
    });

    // E. Calcular Promedio General y Cadena de Seguridad
    const promedioGeneral = materiasConPromedio > 0 ? (sumaPromedios / materiasConPromedio).toFixed(1) : '0.0';
    const fechaImpresion = new Date().toISOString();
    const cadenaOriginal = `||${CCT}|${data.estudiante.matricula}|${promedioGeneral}|${fechaImpresion}||`;


    // --- 3. DEFINICIÓN DEL PDF (PDFMAKE) ---
    const docDefinition: TDocumentDefinitions = {
      displayTitle:true,
      pageSize: 'LETTER',
      // Márgenes: [Izq, Arriba, Der, Abajo]
      // Arriba 110pts para dejar espacio al Encabezado Centrado
      pageMargins: [40, 110, 40, 60], 
      
      // Marca de Agua (Escudo de fondo)
      background: [
        {
          image: this.logoColegio,
          width: 350,
          opacity: 0.04,
          absolutePosition: { x: 130, y: 250 }
        }
      ],

      // --- ENCABEZADO CENTRADO CON LÍNEA ---
      header: {
        margin: [40, 20, 40, 0],
        stack: [
          {
            columns: [
              // 1. Logo (Izquierda)
              { 
                image: this.logoColegio, 
                width: 60 
              },
              // 2. Títulos (TOTALMENTE CENTRADOS)
              {
                width: '*', 
                stack: [
                  { text: 'SISTEMA EDUCATIVO NACIONAL', style: 'headerOfficial', color: grisClaro },
                  { text: 'COLEGIO VIZCAYA DE DURANGO', style: 'headerSchool', color: guinda },
                  { text: `CCT: ${CCT}  |  RVOE: ${RVOE}  |  FECHA: ${FECHA_RVOE}`, style: 'headerMeta' },
                  { text: 'BOLETA DE EVALUACIÓN', style: 'docTitle' }
                ],
                alignment: 'right',
                margin: [0, 5, 0, 0] 
              },
              // 3. QR (Derecha)
              {
                qr: cadenaOriginal,
                fit: 30,
                alignment: 'right',
                foreground: guinda
              }
            ]
          },
          { text: '', margin: [0, 5] },
          // Línea Divisora
          { 
            canvas: [ 
              { type: 'line', x1: 0, y1: 0, x2: 532, y2: 0, lineWidth: 2, lineColor: guinda } 
            ],
            alignment: 'center'
          }
        ]
      },

      content: [
        // A. CAJA DE DATOS DEL ALUMNO
        {
          style: 'studentBox',
          table: {
            widths: ['15%', '40%', '15%', '30%'], // Distribución balanceada
            body: [
              [
                { text: 'ALUMNO:', style: 'label' },
                { text: `${data.estudiante.apellidos} ${data.estudiante.nombre}`.toUpperCase(), style: 'value', colSpan: 3 },
                {}, {}
              ],
              [
                { text: 'MATRÍCULA:', style: 'label' },
                { text: data.estudiante.matricula || '', style: 'value' },
                { text: 'CURP:', style: 'label' },
                { text: data.estudiante.curp, style: 'value' }
              ],
              [
                { text: 'GRADO:', style: 'label' },
                { text: `${data.estudiante.grado}° SEMESTRE`, style: 'value' },
                { text: 'GRUPO:', style: 'label' },
                { text: `"${data.estudiante.grupo}"`, style: 'value' }
              ],
              [
                { text: 'CICLO:', style: 'label' },
                { text: data.cicloEscolar, style: 'value' },
                { text: 'FECHA:', style: 'label' },
                { text: new Date().toLocaleDateString('es-MX', {dateStyle: 'long'}).toUpperCase(), style: 'value' }
              ]
            ]
          },
          layout: {
            hLineWidth: (i) => i === 4 ? 0 : 1, // Solo líneas horizontales
            vLineWidth: () => 0,
            hLineColor: () => lineaSuave,
            paddingTop: () => 4,
            paddingBottom: () => 4
          }
        },

        { text: '', margin: [0, 0, 0, 15] },

        // B. TABLA DE CALIFICACIONES PRINCIPAL
        {
          table: {
            headerRows: 1,
            widths: tableWidths,
            body: tableBody
          },
          layout: {
            // Línea gruesa arriba y abajo, delgada en medio
            hLineWidth: (i, node) => (i === 0 || i === node.table.body.length) ? 2 : 1,
            vLineWidth: () => 0,
            hLineColor: (i) => (i === 0) ? guinda : lineaSuave,
            paddingTop: () => 6,
            paddingBottom: () => 6
          }
        },

        // C. NUEVA SECCIÓN: OBSERVACIONES (Solo si existen)
        materiasConObservacion.length > 0 ? [
          { text: '', margin: [0, 15] },
          { text: 'OBSERVACIONES Y COMENTARIOS DEL PERIODO', style: 'sectionTitle' },
          {
            table: {
              widths: ['30%', '25%', '45%'], // Materia | Docente | Comentario
              body: [
                // Header Sección
                [
                  { text: 'ASIGNATURA', style: 'thSmall' },
                  { text: 'DOCENTE', style: 'thSmall' },
                  { text: 'OBSERVACIÓN', style: 'thSmall' }
                ],
                // Datos
                ...materiasConObservacion.map(m => [
                  { text: m.materia.nombre, style: 'tdSmall', bold: true },
                  { text: m.nombreDocente || 'Docente Asignado', style: 'tdSmall', italics: true, color: guinda },
                  { text: m.observaciones || '', style: 'tdSmall' }
                ])
              ]
            },
            layout: {
              hLineWidth: () => 1,
              vLineWidth: () => 1, // Rejilla completa para las observaciones
              hLineColor: () => lineaSuave,
              vLineColor: () => lineaSuave,
              paddingTop: () => 4,
              paddingBottom: () => 4
            }
          }
        ] : [],

        { text: '', margin: [0, 0, 0, 20] },

        // D. RESUMEN FINAL (Alineado a la derecha)
        {
          columns: [
            { width: '*', text: '' }, // Espacio vacío
            {
              width: 200,
              table: {
                widths: ['*', 60],
                body: [
                  [
                    { text: 'ASIGNATURAS REPROBADAS:', style: 'summaryLabel', alignment: 'right' },
                    { text: reprobadas.toString(), style: 'summaryValue', color: reprobadas > 0 ? '#DC2626' : grisOscuro }
                  ],
                  [
                    { text: 'PROMEDIO FINAL:', style: 'summaryLabel', alignment: 'right', margin: [0, 5, 0, 0] },
                    { text: promedioGeneral, style: 'gpaBig', fillColor: guinda, color: 'white' }
                  ]
                ]
              },
              layout: 'noBorders'
            }
          ]
        },

        { text: '', margin: [0, 0, 0, 50] },

        // E. SECCIÓN DE FIRMAS
        {
          columns: [
            {
              stack: [
                { text: '____________________________________', alignment: 'center', color: grisClaro },
                { text: 'DIRECTOR(A) DEL PLANTEL', style: 'signLabel' },
                { text: 'LIC. LILIANA ORTIZ', style: 'signName' }
              ],
              alignment: 'center'
            },
            {
              stack: [
                { text: '____________________________________', alignment: 'center', color: grisClaro },
                { text: 'CONTROL ESCOLAR', style: 'signLabel' },
                { text: 'COLEGIO VIZCAYA', style: 'signName' }
              ],
              alignment: 'center'
            }
          ]
        },
        
        // F. PIE DIGITAL (Legal)
        {
          stack: [
            { text: 'CADENA DIGITAL DE AUTENTICIDAD', style: 'digitalLabel' },
            { text: cadenaOriginal, style: 'digitalString' },
            { text: 'Este documento ha sido generado electrónicamente y es válido para efectos informativos internos del Colegio Vizcaya.', style: 'legalDisclaimer' }
          ],
          margin: [0, 30, 0, 0]
        }
      ],

      // --- 4. ESTILOS TIPOGRÁFICOS ---
      styles: {
        // Headers
        headerOfficial: { fontSize: 7, characterSpacing: 2, bold: true, margin: [0, 0, 0, 2] },
        headerSchool: { fontSize: 13, bold: true, margin: [0, 0, 0, 2] },
        headerMeta: { fontSize: 7, color: grisOscuro, margin: [0, 0, 0, 4] },
        docTitle: { fontSize: 11, bold: true, color: grisOscuro, characterSpacing: 2, margin: [0, 2, 0, 0] },
        
        // Datos Alumno
        label: { fontSize: 8, color: grisClaro, bold: true, margin: [0, 2] },
        value: { fontSize: 9, color: grisOscuro, bold: true, margin: [0, 2] },
        
        // Tabla Calificaciones
        th: { fontSize: 8, bold: true, color: 'white', fillColor: guinda, margin: [0, 4] },
        td: { fontSize: 9, color: grisOscuro },
        tdProm: { fontSize: 9, bold: true },

        // Tabla Observaciones (Nuevo)
        sectionTitle: { fontSize: 9, bold: true, color: guinda, margin: [0, 0, 0, 5], characterSpacing: 1 },
        thSmall: { fontSize: 7, bold: true, color: 'white', fillColor: grisClaro, margin: [0, 2] },
        tdSmall: { fontSize: 7, color: grisOscuro, margin: [0, 2] },

        // Resumen
        summaryLabel: { fontSize: 8, bold: true, color: grisClaro },
        summaryValue: { fontSize: 9, bold: true, alignment: 'center' },
        gpaBig: { fontSize: 14, bold: true, alignment: 'center', margin: [0, 2] },

        // Firmas y Footer
        signLabel: { fontSize: 7, bold: true, color: grisClaro, margin: [0, 2, 0, 0] },
        signName: { fontSize: 8, bold: true, color: grisOscuro },
        digitalLabel: { fontSize: 6, bold: true, color: guinda },
        digitalString: { fontSize: 6, color: grisClaro, margin: [0, 1] },
        legalDisclaimer: { fontSize: 6, italics: true, color: grisClaro, alignment: 'center', margin: [0, 5] }
      }
    };

    // Generar y Abrir PDF
    pdfMake.createPdf(docDefinition).open();
  }

  
  /**
   * Genera el PDF. Recibe el reporte y los datos del estudiante ya procesados.
   */
  imprimirDetalleMateria(materia: Materia) {
    
    const guinda = '#8C1D40';
    const grisOscuro = '#1F2937';
    const grisClaro = '#6B7280';
    const fondoGris = '#F9FAFB';

    const docDefinition: TDocumentDefinitions = {
      pageSize: 'LETTER',
      pageMargins: [40, 60, 40, 60],
      
      content: [
        // 1. ENCABEZADO
        {
          columns: [
            {
              image: this.logoColegio, 
              width: 50,
              alignment: 'left'
            },
            {
              stack: [
                { text: 'COLEGIO VIZCAYA', style: 'brandTitle' },
                { text: 'CONTROL ESCOLAR - CATÁLOGO ACADÉMICO', style: 'brandSubTitle' },
              ],
              width: '*',
              alignment: 'center',
              margin: [0, 10, 0, 0]
            }
          ]
        },

        // Línea divisora
        { canvas: [{ type: 'line', x1: 0, y1: 15, x2: 532, y2: 15, lineWidth: 3, lineColor: guinda }] },
        { text: '', margin: [0, 0, 0, 20] },

        // 2. TÍTULO
        { text: 'FICHA DE ASIGNATURA', style: 'docTitle' },
        { text: `Fecha de Consulta: ${new Date().toLocaleDateString()}`, style: 'docDate' },

        { text: '', margin: [0, 0, 0, 30] },

        // 3. TARJETA DE DATOS (Tabla grande)
        {
          style: 'materiaCard',
          table: {
            widths: ['30%', '70%'],
            body: [
              // Clave
              [
                { text: 'CLAVE OFICIAL', style: 'labelCell', fillColor: fondoGris },
                { text: materia.claveMateria, style: 'valueCell' }
              ],
              // Nombre
              [
                { text: 'NOMBRE ASIGNATURA', style: 'labelCell', fillColor: fondoGris },
                { text: materia.nombre, style: 'valueCellBold' }
              ],
              // Grado
              [
                { text: 'GRADO ESCOLAR', style: 'labelCell', fillColor: fondoGris },
                { text: `${materia.grado}° Semestre/Grado`, style: 'valueCell' }
              ],
              // ID Interno
              [
                { text: 'ID INTERNO', style: 'labelCell', fillColor: fondoGris },
                { text: materia.id, style: 'valueCellSmall' }
              ]
            ]
          },
          layout: {
            hLineWidth: () => 1,
            vLineWidth: () => 1,
            hLineColor: () => '#e5e7eb',
            vLineColor: () => '#e5e7eb',
          }
        },

        { text: '', margin: [0, 0, 0, 40] },

        // 4. PIE
        {
          text: 'Este documento es informativo para uso interno de la coordinación académica.',
          style: 'footerText',
          absolutePosition: { x: 40, y: 750 }
        }
      ],

      styles: {
        brandTitle: { fontSize: 16, bold: true, color: guinda },
        brandSubTitle: { fontSize: 9, color: grisClaro, characterSpacing: 1, bold: true },
        docTitle: { fontSize: 16, bold: true, color: grisOscuro, alignment: 'center', characterSpacing: 1 },
        docDate: { fontSize: 10, color: grisClaro, alignment: 'center' },
        
        labelCell: { fontSize: 10, bold: true, color: grisClaro, margin: [10, 10] },
        valueCell: { fontSize: 12, color: grisOscuro, margin: [10, 10] },
        valueCellBold: { fontSize: 14, bold: true, color: guinda, margin: [10, 10] },
        valueCellSmall: { fontSize: 9, color: grisClaro, margin: [10, 10], fontFeatures: ['smcp'] },
        
        footerText: { fontSize: 8, color: '#9ca3af', alignment: 'center' }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }


  imprimirReporteIndisciplina(reporte: ReporteIndisciplina, estudiante: PerfilUsuarioDTO) {
    
    // 1. PREPARACIÓN DE DATOS
    const nombreEstudiante = `${estudiante.persona.nombre} ${estudiante.persona.apellidos}`;
    const datosAcademicos = (estudiante.rol as RolEstudiante);
    const matricula = datosAcademicos?.matricula || 'S/N';
    const gradoGrupo = datosAcademicos ? `${datosAcademicos.grado}° "${datosAcademicos.grupo}"` : 'Sin Asignar';

    // --- LÓGICA DE LA FOTO ---
    // Si tiene URL válida (más de 20 chars para asegurar que no es basura), úsala. Si no, default.
    let fotoPerfil = this.defaultAvatar;
    if (estudiante.persona.fotoUrl && estudiante.persona.fotoUrl.length > 20) {
        fotoPerfil = estudiante.persona.fotoUrl;
    }

    // Colores
    const guinda = '#8C1D40';
    const grisOscuro = '#1F2937';
    const grisClaro = '#6B7280';
    const fondoGris = '#F9FAFB';

    // Fechas
    let fechaStr = '---';
    let horaStr = '---';
    try {
      const fecha = new Date(reporte.fecha);
      if(!isNaN(fecha.getTime())){
        fechaStr = fecha.toLocaleDateString('es-MX', { day: '2-digit', month: 'long', year: 'numeric' });
        horaStr = fecha.toLocaleTimeString('es-MX', { hour: '2-digit', minute: '2-digit' });
      }
    } catch(e) {}

    // Color de Severidad
    let colorSev = '#2563eb'; // Azul
    if (reporte.severidad === 'MEDIA') colorSev = '#d97706'; // Naranja
    if (reporte.severidad === 'ALTA') colorSev = '#dc2626'; // Rojo

    // DEFINICIÓN DEL DOCUMENTO
    const docDefinition: TDocumentDefinitions = {
      pageSize: 'LETTER',
      pageMargins: [40, 60, 40, 60],
      
      content: [
        // ENCABEZADO
        {
          columns: [
            {
              // Logo Real
              image: this.logoColegio, // Asegúrate de actualizar la variable logoColegio arriba con tu base64 real
              width: 60,
              alignment: 'left'
            },
            {
              stack: [
                { text: 'COLEGIO VIZCAYA', style: 'brandTitle' },
                { text: 'COORDINACIÓN ACADÉMICA Y DISCIPLINARIA', style: 'brandSubTitle' },
              ],
              width: '*',
              alignment: 'center',
              margin: [0, 10, 0, 0]
            },
            {
              stack: [
                { text: 'FOLIO', style: 'labelTiny', alignment: 'right' },
                { text: `#${reporte.id.substring(0, 6).toUpperCase()}`, style: 'folioText', alignment: 'right' }
              ],
              width: 70
            }
          ]
        },

        // Línea Guinda (Ancho completo)
        { canvas: [{ type: 'line', x1: 0, y1: 15, x2: 532, y2: 15, lineWidth: 3, lineColor: guinda }] },
        { text: '', margin: [0, 0, 0, 20] },

        // Título del Documento
        { text: 'REPORTE DE INCIDENCIA', style: 'docTitle' },
        
        { text: '', margin: [0, 0, 0, 20] },

        // FICHA DEL ALUMNO (Estilo Tarjeta)
        {
          style: 'studentCard',
          table: {
            widths: [80, '*', 100],
            body: [
              [
                // Foto
                {
                  image: fotoPerfil,
                  fit: [70, 70],
                  alignment: 'center',
                  margin: [0, 5, 10, 5]
                },
                // Datos
                {
                  stack: [
                    { text: 'ALUMNO(A):', style: 'labelTiny' },
                    { text: nombreEstudiante.toUpperCase(), style: 'studentName' },
                    { text: `MATRÍCULA: ${matricula}`, style: 'dataText', margin: [0, 5, 0, 0] }
                  ],
                  margin: [5, 10, 0, 10]
                },
                // Grado (Badge)
                {
                  fillColor: guinda,
                  stack: [
                    { text: 'GRADO Y GRUPO', color: 'white', fontSize: 7, bold: true, alignment: 'center', margin: [0, 15, 0, 2] },
                    { text: gradoGrupo, color: 'white', fontSize: 14, bold: true, alignment: 'center' }
                  ],
                  margin: [-5, -5, -5, -5] // Hack para llenar celda
                }
              ]
            ]
          },
          layout: {
            defaultBorder: false,
            hLineColor: () => '#e5e7eb',
            hLineWidth: (i) => (i === 1 ? 1 : 0), // Solo línea abajo
          }
        },

        { text: '', margin: [0, 0, 0, 25] },

        // TABLA DE DETALLES
        {
          table: {
            widths: ['*', '*', '*'],
            body: [
              [
                { text: 'FECHA', style: 'tableHeader', fillColor: fondoGris },
                { text: 'HORA', style: 'tableHeader', fillColor: fondoGris },
                { text: 'SEVERIDAD', style: 'tableHeader', fillColor: fondoGris }
              ],
              [
                { text: fechaStr, style: 'tableCell' },
                { text: horaStr, style: 'tableCell' },
                { text: (reporte.severidad || 'NORMAL').toUpperCase(), style: 'tableCell', bold: true, color: colorSev }
              ]
            ]
          },
          layout: {
            hLineWidth: () => 1,
            vLineWidth: () => 0,
            hLineColor: () => '#e5e7eb'
          }
        },

        { text: '', margin: [0, 0, 0, 20] },

        // DESCRIPCIÓN
        { text: 'DESCRIPCIÓN DE LOS HECHOS:', style: 'labelSmall' },
        {
          text: reporte.descripcion || 'Sin descripción detallada.',
          style: 'narrativeBox'
        },

        { text: '', margin: [0, 0, 0, 60] },

        // FIRMAS
        {
          columns: [
            {
              stack: [
                { canvas: [{ type: 'line', x1: 20, y1: 0, x2: 200, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'DOCENTE / REPORTANTE', style: 'signatureLabel' }
              ],
              alignment: 'center'
            },
            {
              stack: [
                { canvas: [{ type: 'line', x1: 20, y1: 0, x2: 200, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'ENTERADO (ALUMNO/TUTOR)', style: 'signatureLabel' }
              ],
              alignment: 'center'
            }
          ]
        },

        // PIE
        {
          text: 'Este documento es confidencial y para uso exclusivo interno.',
          style: 'footerText',
          absolutePosition: { x: 40, y: 750 }
        }
      ],

      styles: {
        brandTitle: { fontSize: 16, bold: true, color: guinda },
        brandSubTitle: { fontSize: 8, color: grisClaro, characterSpacing: 1.5, bold: true },
        docTitle: { fontSize: 14, bold: true, color: grisOscuro, alignment: 'center', characterSpacing: 1 },
        docDate: { fontSize: 10, color: grisClaro, alignment: 'center' },
        labelTiny: { fontSize: 7, color: grisClaro, bold: true },
        labelSmall: { fontSize: 9, color: guinda, bold: true, margin: [0, 0, 0, 5] },
        studentName: { fontSize: 12, bold: true, color: grisOscuro },
        dataText: { fontSize: 10, color: grisOscuro },
        folioText: { fontSize: 10, bold: true, color: guinda },
        tableHeader: { fontSize: 8, bold: true, color: grisClaro, margin: [5, 5, 5, 5] },
        tableCell: { fontSize: 10, color: grisOscuro, margin: [5, 8, 5, 8] },
        narrativeBox: { fontSize: 11, color: '#374151', lineHeight: 1.6, alignment: 'justify' },
        signatureLabel: { fontSize: 8, color: grisClaro, bold: true, margin: [5, 0, 0, 0] },
        footerText: { fontSize: 7, color: '#9ca3af', alignment: 'center' }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }

  /**
   * Genera el Expediente del Docente (Diseño Premium Vizcaya)
   */
  imprimirExpedienteDocente(docente: PerfilUsuarioDTO, grupos: GrupoDetalle[]) {
    const rol = docente.rol as RolEmpleado;
    
    // Paleta de Colores Institucional
    const guinda = '#8C1D40';
    const grisOscuro = '#1F2937';
    const grisMedio = '#4B5563';
    const grisClaro = '#9CA3AF';
    const fondoGris = '#F3F4F6';

    // --- 1. PREPARAR DATOS ---
    let fotoPerfil = this.defaultAvatar;
    if (docente.persona.fotoUrl && docente.persona.fotoUrl.startsWith('data:image')) {
        fotoPerfil = docente.persona.fotoUrl;
    }

    // Tabla de Grupos (Estilo Zebra y Header Guinda)
    const tableBodyGrupos: any[] = [
      [
        { text: 'ASIGNATURA', style: 'th', fillColor: guinda, color: 'white', border: [false, false, false, false] },
        { text: 'GRADO', style: 'th', fillColor: guinda, color: 'white', alignment: 'center', border: [false, false, false, false] },
        { text: 'CICLO ESCOLAR', style: 'th', fillColor: guinda, color: 'white', alignment: 'center', border: [false, false, false, false] },
        { text: 'ALUMNOS', style: 'th', fillColor: guinda, color: 'white', alignment: 'center', border: [false, false, false, false] }
      ]
    ];

    if (grupos.length > 0) {
      grupos.forEach((g, index) => {
        const bgRow = index % 2 === 0 ? 'white' : '#f9fafb'; // Zebra
        tableBodyGrupos.push([
          { text: g.materia?.nombre || '---', style: 'tdBold', fillColor: bgRow, border: [false, false, false, true], borderColor: ['','','','#e5e7eb'] },
          { text: `${g.materia?.grado}° Semestre`, style: 'td', alignment: 'center', fillColor: bgRow, border: [false, false, false, true], borderColor: ['','','','#e5e7eb'] },
          { text: g.cicloEscolar, style: 'td', alignment: 'center', fillColor: bgRow, border: [false, false, false, true], borderColor: ['','','','#e5e7eb'] },
          { text: (g.estudianteUids?.length || 0).toString(), style: 'td', alignment: 'center', fillColor: bgRow, border: [false, false, false, true], borderColor: ['','','','#e5e7eb'] }
        ]);
      });
    } else {
      tableBodyGrupos.push([{ text: 'Sin carga académica asignada.', colSpan: 4, style: 'td', alignment: 'center', italics: true, color: grisClaro }, {}, {}, {}]);
    }

    // --- 2. DEFINICIÓN DEL PDF ---
    const docDefinition: TDocumentDefinitions = {
      pageSize: 'LETTER',
      pageMargins: [40, 40, 40, 60], // Márgenes limpios
      
      content: [
        
        // A. ENCABEZADO (Logo y Títulos alineados)
        {
          columns: [
            {
              image: this.logoColegio,
              width: 65
            },
            {
              stack: [
                { text: 'COLEGIO VIZCAYA', style: 'headerSchool' },
                { text: 'DIRECCIÓN ACADÉMICA', style: 'headerDept' },
                { text: 'EXPEDIENTE DE PERSONAL DOCENTE', style: 'headerDoc', margin: [0, 15, 0, 0] }
              ],
              alignment: 'right',
              width: '*'
            }
          ]
        },

        // Línea de acento
        { canvas: [{ type: 'rect', x: 0, y: 0, w: 532, h: 3, color: guinda }], margin: [0, 15, 0, 25] },

        // B. TARJETA DE PRESENTACIÓN (Foto y Datos Principales)
        {
          style: 'profileCard',
          table: {
            widths: [100, '*'],
            body: [
              [
                // Columna Foto
                {
                  image: fotoPerfil,
                  fit: [90, 90],
                  alignment: 'center',
                  border: [false, false, true, false], // Línea vertical divisoria
                  borderColor: ['','','#e5e7eb','']
                },
                // Columna Datos
                {
                  stack: [
                    { text: `${docente.persona.nombre} ${docente.persona.apellidos}`.toUpperCase(), style: 'profileName' },
                    { text: 'DOCENTE TITULAR', style: 'profileRole', color: guinda },
                    { text: docente.persona.email, style: 'profileEmail', margin: [0, 5, 0, 0] },
                    { 
                      text: [
                        { text: 'ID EMPLEADO: ', color: grisClaro, fontSize: 9, bold: true },
                        { text: docente.persona.uid.substring(0, 8).toUpperCase(), fontSize: 10, bold: true, color: grisOscuro }
                      ],
                      margin: [0, 10, 0, 0]
                    }
                  ],
                  margin: [15, 5, 0, 5],
                  border: [false, false, false, false]
                }
              ]
            ]
          },
          layout: 'noBorders' // Usamos bordes manuales
        },

        { text: '', margin: [0, 0, 0, 25] },

        // C. INFORMACIÓN LEGAL (Grid de 3 columnas elegante)
        {
          table: {
            widths: ['*', '*', '*'],
            body: [
              [
                { text: 'CURP', style: 'label' },
                { text: 'RFC', style: 'label' },
                { text: 'CÉDULA PROFESIONAL', style: 'label' }
              ],
              [
                { text: docente.persona.curp, style: 'valueBox' },
                { text: rol?.RFC || '---', style: 'valueBox' },
                { text: rol?.cedulaProfesional || 'EN TRÁMITE', style: 'valueBox' }
              ]
            ]
          },
          layout: 'noBorders'
        },

        { text: '', margin: [0, 0, 0, 35] },

        // D. CARGA ACADÉMICA (Tabla Premium)
        {
          text: 'CARGA ACADÉMICA ACTUAL',
          style: 'sectionTitle'
        },
        { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 50, y2: 0, lineWidth: 2, lineColor: guinda }], margin: [0, 2, 0, 10] },

        {
          table: {
            headerRows: 1,
            widths: ['*', 70, 90, 70], // Anchos ajustados
            body: tableBodyGrupos
          },
          layout: {
            hLineWidth: (i) => 0,
            vLineWidth: () => 0,
            paddingTop: () => 8,
            paddingBottom: () => 8
          }
        },

        { text: '', margin: [0, 0, 0, 60] },

        // E. FIRMAS
        {
          columns: [
            {
              stack: [
                { canvas: [{ type: 'line', x1: 10, y1: 0, x2: 180, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'VALIDACIÓN ACADÉMICA', style: 'signLabel' }
              ],
              alignment: 'center'
            },
            {
              stack: [
                { canvas: [{ type: 'line', x1: 10, y1: 0, x2: 180, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'FIRMA DEL DOCENTE', style: 'signLabel' }
              ],
              alignment: 'center'
            }
          ]
        }
      ],

      // --- ESTILOS ---
      styles: {
        headerSchool: { fontSize: 16, bold: true, color: guinda, characterSpacing: 0.5 },
        headerDept: { fontSize: 10, color: grisClaro, bold: true, characterSpacing: 2, margin: [0, 2, 0, 0] },
        headerDoc: { fontSize: 12, color: grisOscuro, bold: true },

        // Perfil
        profileName: { fontSize: 16, bold: true, color: grisOscuro },
        profileRole: { fontSize: 12, bold: true, characterSpacing: 1, margin: [0, 2, 0, 0] },
        profileEmail: { fontSize: 10, color: grisMedio },

        // Info Grid
        label: { fontSize: 8, color: grisClaro, bold: true, margin: [0, 0, 0, 3] },
        valueBox: { 
          fontSize: 11, color: grisOscuro, bold: true, 
          fillColor: fondoGris, margin: [0, 0, 5, 0] // Fondo gris en el dato para resaltar
        },

        // Secciones
        sectionTitle: { fontSize: 12, bold: true, color: guinda },

        // Tabla Académica
        th: { fontSize: 9, bold: true, margin: [0, 3] },
        td: { fontSize: 9, color: grisMedio, margin: [0, 3] },
        tdBold: { fontSize: 9, color: grisOscuro, bold: true, margin: [0, 3] },

        signLabel: { fontSize: 8, color: grisClaro, bold: true, margin: [5, 0, 0, 0] }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }

  /**
   * Genera el Acta de Calificaciones para una Evaluación específica.
   * Diseño: Oficial Institucional (Lista Vertical).
   */
  imprimirActaEvaluacion(datos: {
    docenteNombre: string;
    materia: string;
    gradoGrupo: string;
    periodo: string;
    rubro: string; // Ej: "Examen Parcial 1 (40%)"
    alumnos: any[]; // La lista de alumnos con sus notas
  }) {
    
    // Configuración visual
    const guinda = '#8C1D40';
    const grisOscuro = '#1F2937';
    const grisClaro = '#6B7280';
    const bordeTabla = '#E5E7EB';

    // 1. Construir filas de la tabla
    const bodyTabla = [
      // Encabezados
      [
        { text: 'NO.', style: 'th', fillColor: '#f3f4f6' },
        { text: 'MATRÍCULA', style: 'th', fillColor: '#f3f4f6' },
        { text: 'NOMBRE DEL ESTUDIANTE', style: 'th', fillColor: '#f3f4f6', alignment: 'left' },
        { text: 'CALIFICACIÓN', style: 'th', fillColor: '#f3f4f6' },
        { text: 'ESTATUS', style: 'th', fillColor: '#f3f4f6' },
        { text: 'OBSERVACIONES', style: 'th', fillColor: '#f3f4f6', alignment: 'left' }
      ]
    ];

    // Filas de datos
    datos.alumnos.forEach((a, index) => {
      const calif = a.calificacion ?? '-';
      let colorNota = grisOscuro;
      let estatusTexto = '-';
      
      // Lógica visual simple para el PDF
      if (a.calificacion !== null) {
        if (a.calificacion < 6) { colorNota = '#ef4444'; estatusTexto = 'REP'; }
        else if (a.calificacion >= 9) { colorNota = '#059669'; estatusTexto = 'EXC'; }
        else { estatusTexto = 'APR'; }
      }

      bodyTabla.push([
        { text: (index + 1).toString(), fillColor: "",  style: 'td', alignment: 'center' },
        { text: a.matricula, style: 'td', alignment: 'center', fillColor: "" },
        { text: a.nombre.toUpperCase(), fillColor: "", style: 'tdBold', alignment: 'left' },
        { text: calif.toString(), style: 'tdBold', alignment: 'center', fillColor: colorNota},
        { text: estatusTexto, style: 'td', alignment: 'center', fillColor: "", },
        { text: a.observaciones || '', style: 'td', fillColor: grisClaro }
      ]);
    });

    // 2. Definición del Documento
    const docDefinition: any = {
      pageSize: 'LETTER',
      pageMargins: [40, 60, 40, 60],
      
      content: [
        // --- ENCABEZADO INSTITUCIONAL ---
        {
          columns: [
            { 
              // Logo (Reemplaza con tu base64 real)
              image: this.logoColegio || '', 
              width: 50 
            },
            {
              stack: [
                { text: 'COLEGIO VIZCAYA', style: 'brandTitle' },
                { text: 'DIRECCIÓN ACADÉMICA - CONTROL ESCOLAR', style: 'brandSub' },
                { text: 'ACTA DE CALIFICACIONES POR RUBRO', style: 'docTitle', margin: [0, 5, 0, 0] }
              ],
              alignment: 'center',
              width: '*'
            },
            { 
              // Espacio para balancear o código QR
              qr: `${datos.materia}-${datos.rubro}`, fit: 45, alignment: 'right' 
            }
          ]
        },
        
        { canvas: [{ type: 'line', x1: 0, y1: 10, x2: 532, y2: 10, lineWidth: 2, lineColor: guinda }] },
        { text: '', margin: [0, 0, 0, 15] },

        // --- DATOS DEL GRUPO (Grid Info) ---
        {
          style: 'infoBox',
          table: {
            widths: ['*', '*', '*'],
            body: [
              [
                { text: 'ASIGNATURA', style: 'label' },
                { text: 'DOCENTE TITULAR', style: 'label' },
                { text: 'PERIODO / EVALUACIÓN', style: 'label' }
              ],
              [
                { text: `${datos.materia}\n${datos.gradoGrupo}`, style: 'value' },
                { text: datos.docenteNombre, style: 'value' },
                { text: `${datos.periodo}\n${datos.rubro}`, style: 'value' }
              ]
            ]
          },
          layout: 'noBorders'
        },

        { text: '', margin: [0, 0, 0, 20] },

        // --- TABLA DE ALUMNOS ---
        {
          table: {
            headerRows: 1,
            widths: [25, 60, '*', 50, 40, 100],
            body: bodyTabla
          },
          layout: {
            hLineWidth: (i: number) => (i === 0 || i === 1) ? 1 : 0.5,
            vLineWidth: () => 0,
            hLineColor: (i: number) => (i === 0) ? guinda : bordeTabla,
            paddingTop: () => 8,
            paddingBottom: () => 8
          }
        },

        { text: '', margin: [0, 0, 0, 40] },

        // --- FIRMAS ---
        {
          columns: [
            {
              stack: [
                { canvas: [{ type: 'line', x1: 10, y1: 0, x2: 180, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'FIRMA DEL DOCENTE', style: 'signLabel' }
              ],
              alignment: 'center'
            },
            {
              stack: [
                { canvas: [{ type: 'line', x1: 10, y1: 0, x2: 180, y2: 0, lineWidth: 1, lineColor: grisOscuro }] },
                { text: 'SELLO DE COORDINACIÓN', style: 'signLabel' }
              ],
              alignment: 'center'
            }
          ]
        },

        // --- PIE DE PÁGINA ---
        {
          text: `Documento generado el ${new Date().toLocaleDateString()} a las ${new Date().toLocaleTimeString()}`,
          style: 'footer',
          absolutePosition: { x: 40, y: 750 }
        }
      ],

      styles: {
        brandTitle: { fontSize: 14, bold: true, color: guinda },
        brandSub: { fontSize: 8, bold: true, color: grisClaro, letterSpacing: 1 },
        docTitle: { fontSize: 12, bold: true, color: grisOscuro, margin: [0, 5] },
        
        label: { fontSize: 7, bold: true, color: grisClaro, margin: [0, 0, 0, 2] },
        value: { fontSize: 10, bold: true, color: grisOscuro, margin: [0, 0, 0, 10] },
        
        th: { fontSize: 8, bold: true, color: grisOscuro, alignment: 'center' },
        td: { fontSize: 9, color: grisOscuro },
        tdBold: { fontSize: 9, bold: true, color: grisOscuro },
        
        signLabel: { fontSize: 8, bold: true, color: grisClaro, margin: [0, 5, 0, 0] },
        footer: { fontSize: 8, color: '#9ca3af', alignment: 'center' }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }

  /**
   * Genera el PDF de la Credencial (Tamaño Tarjeta Vertical).
   * Frente en Página 1, Reverso en Página 2.
   */
  imprimirCredencial(estudiante: PerfilUsuarioDTO) {
    
    const guinda = '#8C1D40';
    const dorado = '#Bfa15f';
    const grisTexto = '#374151';

    // Datos del Estudiante
    const nombreCompleto = `${estudiante.persona.nombre}\n${estudiante.persona.apellidos}`.toUpperCase();
    const matricula = (estudiante.rol as any)?.matricula || 'S/N';
    const grupo = `${(estudiante.rol as any)?.grado}° "${(estudiante.rol as any)?.grupo}"`;
    const foto = estudiante.persona.fotoUrl || null; // Manejar si tiene foto o no

    // Definición del Documento (Tamaño Tarjeta Personalizado)
    const docDefinition: any = {
      pageSize: { width: 242, height: 380 }, // Tamaño aprox Credencial vertical un poco más grande para mejor calidad
      pageMargins: [0, 0, 0, 0], // Sin márgenes, diseño full bleed
      
      content: [
        // --- PÁGINA 1: FRENTE ---
        {
          stack: [
            // Fondo Superior Curvo (Simulado con tabla o formas vectoriales si pdfMake lo permite, aquí usaremos bloques de color)
            {
              canvas: [
                { type: 'rect', x: 0, y: 0, w: 242, h: 120, color: guinda },
                // Elipse para efecto curvo abajo
                // Nota: pdfMake básico no soporta bezier curves complejas fácilmente, usamos bloque sólido para estabilidad
              ],
              absolutePosition: { x: 0, y: 0 }
            },
            // Logo y Texto Header
            {
              image: this.logoColegio, // Tu logo en base64
              width: 40,
              alignment: 'center',
              margin: [0, 20, 0, 5]
            },
            {
              text: 'COLEGIO VIZCAYA',
              style: 'credHeader',
              alignment: 'center',
              color: 'white'
            },
            
            // FOTO (Círculo simulado, o cuadrado redondeado)
            {
              image: foto ? foto : this.logoColegio, // Fallback si no hay foto
              width: 90,
              height: 90,
              alignment: 'center',
              margin: [0, 15, 0, 10]
              // cover: { width: 90, height: 90, valign: "center", align: "center" } // Si tu versión de pdfMake soporta 'cover'
            },

            // Nombre
            {
              text: nombreCompleto,
              style: 'credName',
              alignment: 'center',
              color: grisTexto,
              margin: [10, 5]
            },

            // Datos Académicos
            {
              columns: [
                { text: `MATRÍCULA\n${matricula}`, style: 'credLabel', alignment: 'center' },
                { text: `GRADO\n${grupo}`, style: 'credLabel', alignment: 'center' }
              ],
              margin: [0, 10]
            },

            // Badge "ESTUDIANTE"
            {
              table: {
                widths: ['*'],
                body: [[ { text: 'ESTUDIANTE', style: 'credBadge', alignment: 'center', fillColor: dorado, color: 'white', border: [false, false, false, false] } ]]
              },
              margin: [60, 15, 60, 0]
            }
          ]
        },

        // Salto de página para el reverso
        { text: '', pageBreak: 'after' },

        // --- PÁGINA 2: REVERSO ---
        {
          stack: [
             { text: 'USO EXCLUSIVO INSTITUCIONAL', style: 'credLegal', alignment: 'center', margin: [0, 30, 0, 20] },
             
             // Cuadro Emergencia
             {
               stack: [
                 { text: 'EN CASO DE EMERGENCIA:', fontSize: 7, bold: true, color: guinda },
                 { text: '618-123-4567', fontSize: 12, bold: true, margin: [0, 2] }
               ],
               alignment: 'center',
               margin: [20, 10],
               // border simulado
             },

             { canvas: [{ type: 'line', x1: 40, y1: 100, x2: 200, y2: 100, lineWidth: 1, lineColor: '#333' }], margin: [0, 60, 0, 5] },
             { text: 'AUTORIDAD ESCOLAR', fontSize: 7, bold: true, alignment: 'center' },

             // QR
             {
               qr: `ALUMNO:${matricula}|VIGENCIA:2026`,
               fit: 60,
               alignment: 'center',
               margin: [0, 20]
             },

             { text: 'Av. Universidad, Durango, Dgo.', fontSize: 6, color: '#999', alignment: 'center', margin: [0, 10] }
          ]
        }
      ],

      styles: {
        credHeader: { fontSize: 10, bold: true, letterSpacing: 1 },
        credName: { fontSize: 12, bold: true, color: '#333' },
        credLabel: { fontSize: 8, bold: true, color: '#555', lineHeight: 1.2 },
        credBadge: { fontSize: 9, bold: true, margin: [0, 3] },
        credLegal: { fontSize: 6, italics: true, color: '#666' }
      }
    };

    pdfMake.createPdf(docDefinition).open();
  }
}